<?php
declare(strict_types=1);
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/services-fixture.php';require __DIR__.'/commerce-fixture.php';
use Hostider\Core\Database\Migrator;use Hostider\Core\Id;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\Principal;use Hostider\Services\{Engine,Worker,Policies,Transfers};use Hostider\Hosting\Pools;
$db=integrationDb();(new Migrator($db,dirname(__DIR__).'/migrations'))->migrate();
function transferFixture($db,string $scope='SERVICE'): array
{
    $f=serviceFixture($db);(new Pools($db,$f['config']))->configure($f['product']);$engine=new Engine($db,$f['config']);$id=$engine->discover($f['order']['id'],$f['actor'],Id::uuid())[0];(new Worker($db,$f['config']))->once($f['actor'],$engine->repository->find($id,lock:false)['current_operation_id']);$commerce=new \Hostider\Commerce\Services($db,$f['config']);$sender=commerceUser($commerce,'service-sender');$recipient=commerceUser($commerce,'service-recipient');$db->execute("UPDATE identity_customers SET currency='USD' WHERE id=?",[$recipient['customer']]);
    $db->execute('INSERT INTO identity_memberships(user_id,customer_id,is_owner) VALUES (?,?,TRUE)',[$sender['user'],$f['customer']]);$role=$db->execute("SELECT id FROM identity_roles WHERE name='Müşteri Sahibi'")->fetchColumn();$db->transaction(fn()=>$commerce->identity->assign($sender['user'],$role,$f['customer']));$commerce->identity->switchCustomer($sender['reference'],'client',$f['customer']);$policies=new Policies($db,$f['config']);$admin=new Principal('transfer-policy-admin',['services.policy'],staff:true,mfa:true,expiresAt:time()+3600,verifiedAt:time(),administrative:true);$db->transaction(fn()=>$policies->set('SERVICE',$id,['allow_transfer'=>true,'transfer_ttl_seconds'=>30,'transfer_debt_scope'=>$scope],0,$admin));$transfers=new Transfers($db,$f['config']);return $f+compact('engine','id','commerce','sender','recipient','policies','admin','transfers');
}
test('F3-E two real Identity owners transfer service without rewriting financial history',function()use($db): void{
    $f=transferFixture($db);$before=$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn();$period=$f['engine']->repository->find($f['id'],lock:false)['current_period_id'];$request=$f['transfers']->start($f['id'],$f['customer'],$f['recipient']['customer'],$f['sender']['reference'],Id::uuid());same(404,raises(HttpError::class,fn()=>$f['transfers']->accept($request['transfer_id'],$f['recipient']['customer'],str_repeat('0',64),$f['recipient']['reference'],Id::uuid()))->status);$result=$f['transfers']->accept($request['transfer_id'],$f['recipient']['customer'],$request['recipient_token'],$f['recipient']['reference'],Id::uuid());same(true,$result['ownership_changed']);same(404,raises(HttpError::class,fn()=>$f['engine']->repository->find($f['id'],$f['customer'],false))->status);same($f['recipient']['customer'],$f['engine']->repository->find($f['id'],$f['recipient']['customer'],false)['customer_id']);same($f['customer'],$db->execute('SELECT customer_id FROM svc_periods WHERE id=?',[$period])->fetchColumn());same($f['customer'],$db->execute('SELECT customer_id FROM billing_requests WHERE id=?',[$f['order']['payment_request_id']])->fetchColumn());same(404,raises(HttpError::class,fn()=>$f['commerce']->billing->detail($f['order']['payment_request_id'],$f['recipient']['customer']))->status);same($before,$db->execute('SELECT COUNT(*) FROM finance_journals')->fetchColumn());same(2,(int)$db->execute('SELECT COUNT(*) FROM svc_ownership_history WHERE service_id=?',[$f['id']])->fetchColumn());same($f['recipient']['customer'],$db->execute('SELECT customer_id FROM identity_resource_scopes WHERE service_id=?',[$f['id']])->fetchColumn());
});
test('F3-E explicit customer debt policy rejects unrelated open debt without guessing G-T01',function()use($db): void{
    $f=transferFixture($db,'CUSTOMER');same(409,raises(HttpError::class,fn()=>$f['transfers']->start($f['id'],$f['customer'],$f['recipient']['customer'],$f['sender']['reference'],Id::uuid()))->status);same($f['customer'],$f['engine']->repository->find($f['id'],lock:false)['customer_id']);same(0,(int)$db->execute('SELECT COUNT(*) FROM svc_transfers WHERE service_id=?',[$f['id']])->fetchColumn());
});
test('F3-E expired approval and revoked sender session cannot complete ownership change',function()use($db): void{
    $f=transferFixture($db);$request=$f['transfers']->start($f['id'],$f['customer'],$f['recipient']['customer'],$f['sender']['reference'],Id::uuid());$expiry=(int)$db->execute('SELECT UNIX_TIMESTAMP(expires_at) FROM svc_transfers WHERE id=?',[$request['transfer_id']])->fetchColumn();$db->execute('SET timestamp='.($expiry+1));try{same(409,raises(HttpError::class,fn()=>$f['transfers']->accept($request['transfer_id'],$f['recipient']['customer'],$request['recipient_token'],$f['recipient']['reference'],Id::uuid()))->status);}finally{$db->execute('SET timestamp=0');}
    $f=transferFixture($db);$request=$f['transfers']->start($f['id'],$f['customer'],$f['recipient']['customer'],$f['sender']['reference'],Id::uuid());$db->transaction(fn()=>$f['commerce']->identity->invalidate($f['sender']['user']));same(401,raises(HttpError::class,fn()=>$f['transfers']->accept($request['transfer_id'],$f['recipient']['customer'],$request['recipient_token'],$f['recipient']['reference'],Id::uuid()))->status);same($f['customer'],$f['engine']->repository->find($f['id'],lock:false)['customer_id']);
});
runTests();
